INSERT INTO atencion_cliente (id, Consulta, Respuesta, estado_respuesta, fecha_creacion, fecha_respuesta, id_categoria, id_urgencia, valoracion, origen) VALUES
(1,'He olvidado mi contraseña','Usa la opción de recuperar contraseña en la pantalla de inicio de sesión: recibirás un enlace en el correo de tu cuenta. Por seguridad, nunca te pediremos tu contraseña por el chat.','respondida','2026-10-14 09:15:00','2026-10-14 09:15:00',2,2,1,'sintetico'),
(1,'¿A partir de cuánto es gratis el envío?','El envío es gratuito para pedidos superiores a 50 euros. Por debajo de ese importe, el coste se muestra antes de confirmar la compra.','respondida','2026-09-27 17:07:00','2026-09-27 17:07:00',5,3,1,'sintetico'),
(1,'¿Cómo hago una devolución?','Debes solicitar la devolución desde tu cuenta de cliente, en el apartado Mis pedidos. Recibirás las instrucciones para el envío de vuelta.','respondida','2026-09-19 17:25:00','2026-09-19 17:25:00',5,2,1,'sintetico'),
(1,'Quiero hablar con una persona','Soy SofíaIA, el asistente virtual. Si necesitas a una persona, déjalo por escrito y te responderemos el siguiente día laborable (L–V, 9:00–18:00).','respondida','2026-09-18 10:18:00','2026-09-18 10:18:00',3,2,NULL,'sintetico'),
(1,'¿A qué hora puedo hablar con una persona?','Atendemos de lunes a viernes, de 9:00 a 18:00 (hora peninsular). Sábados, domingos y festivos nacionales no atendemos, pero puedes dejar tu consulta por escrito y te responderemos el siguiente día laborable.','respondida','2026-09-19 12:35:00','2026-09-19 12:35:00',3,3,1,'sintetico'),
(1,'¿Qué plazo de entrega tenéis?','El envío suele tardar entre 2 y 5 días laborables desde que el pedido sale del almacén; el plazo exacto depende del destino.','respondida','2026-09-12 09:35:00','2026-09-12 09:35:00',1,2,1,'sintetico'),
(1,'Me ha fallado el pago con tarjeta','Comprueba los datos de la tarjeta o prueba con otro método de pago. Utilizamos sistemas de pago seguros y no guardamos los datos completos de tu tarjeta.','respondida','2026-09-16 18:34:00','2026-09-16 18:34:00',4,1,1,'sintetico'),
(1,'El producto llegó defectuoso','Lamentamos el problema. Indícalo desde tu cuenta con una foto y el número de pedido: gestionaremos la devolución o el cambio sin coste para ti.','respondida','2026-10-19 15:23:00','2026-10-19 15:23:00',1,1,1,'sintetico'),
(1,'¿Hasta cuándo puedo devolver mi compra?','Dispones de 30 días naturales desde la recepción del pedido para devolver un producto.','respondida','2026-09-23 20:15:00','2026-09-23 20:15:00',5,2,1,'sintetico'),
(1,'Quiero cancelar mi pedido','Puedes cancelar el pedido antes de que sea enviado: entra en tu cuenta, abre el pedido y pulsa Cancelar pedido. Si no aparece esa opción, ya fue enviado y puedes devolverlo cuando lo recibas. El reembolso se hace por el mismo método de pago.','respondida','2026-10-11 19:28:00','2026-10-11 19:28:00',5,1,1,'sintetico'),
(1,'Quiero que borréis mis datos','Puedes modificar tus datos desde tu perfil y solicitar el acceso, la rectificación o la supresión escribiendo al equipo de atención. Tus consultas pueden ser procesadas por una IA de un proveedor externo y solo se envía la información necesaria.','respondida','2026-09-04 16:26:00','2026-09-04 16:26:00',3,2,1,'sintetico'),
